import math

def build_agent(sandbox):
    # Lower barriers (small/medium separation)
    bar1 = sandbox.add_static_beam(x=5.6, y=1.92, width=0.8, height=0.2, angle=0, density=50.0)
    sandbox.set_material_properties(bar1, restitution=0.0)
    bar2 = sandbox.add_static_beam(x=6.4, y=1.92, width=0.8, height=0.2, angle=0, density=50.0)
    sandbox.set_material_properties(bar2, restitution=0.0)

    # Upper barriers (medium/large separation)
    bar3 = sandbox.add_static_beam(x=5.6, y=2.35, width=0.8, height=0.2, angle=0, density=50.0)
    sandbox.set_material_properties(bar3, restitution=0.0)
    bar4 = sandbox.add_static_beam(x=6.4, y=2.35, width=0.8, height=0.2, angle=0, density=50.0)
    sandbox.set_material_properties(bar4, restitution=0.0)

    # Deflectors to guide large particles upward and small particles downward
    deflector1 = sandbox.add_static_beam(x=6.8, y=2.35, width=0.08, height=0.2, angle=math.radians(45), density=50.0)
    sandbox.set_material_properties(deflector1, restitution=0.0)
    deflector2 = sandbox.add_static_beam(x=5.5, y=2.35, width=0.08, height=0.2, angle=math.radians(-45), density=50.0)
    sandbox.set_material_properties(deflector2, restitution=0.0)

    return bar1

def agent_action(sandbox, agent_body, step_count):
    if step_count % 32 != 0:
        return
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -30.0))  # Push small particles down
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -25.5))  # Push medium particles up
    for p in sandbox.get_particles_large():
        if p.active and p.position.y < 2.52:
            sandbox.apply_force(p, (0, 10.0))  # Push large particles up
